package fft

import "github.com/go-fft/fft/internal/kernels"

// fused2048Enabled is whether a fused plan of 2048 points runs the one-kernel
// transform (kernels.Fused2048, generated by internal/genfused256): two fused
// passes (64 x 32), the twiddles between them folded into the first. A variable
// for the same reasons as fused256Enabled. The half-length complex plan of a
// real transform of 4096 points is such a plan (RealPlan calls Plan.execute), so
// RFFT of 4096 takes it too.
var fused2048Enabled = kernels.Fused2048On

// fused2048Route reports whether a fused plan of n points takes the kernel.
// Exact and NoFMA plans never do (their arithmetic is not fused), and nor does
// any CPU but the Zen 4 and the Cascade Lake it was measured on (go-fft/fft#162;
// kernels.Fused2048On).
func fused2048Route(n int) bool {
	if n == 2048 && fused2048Enabled {
		kernels.Fused2048Prepare()
		return true
	}
	return false
}
